function canWinNim(n) {
  // win[i]: can the player to move win with i stones left? Each state depends only on the three before it,
  // so once three consecutive states repeat, the whole sequence repeats with that period.
  const win = [false];
  const seen = new Map();
  for (let i = 1; ; i++) {
    if (i > n) return win[n];
    win.push([1, 2, 3].some(t => t <= i && !win[i - t]));
    if (i >= 3) {
      const key = `${win[i - 2]},${win[i - 1]},${win[i]}`;
      if (seen.has(key)) {
        const start = seen.get(key);
        return win[start + (n - start) % (i - start)];
      }
      seen.set(key, i);
    }
  }
}

